#!/bin/bash
# === Ozawa Traders deploy — italray palette + page-navy + Manrope nav + slider polish ===
# Generated: 2026-05-18T14:37:57.236Z
# Paste this entire script into AWS Session Manager (logged in as ec2-user or ubuntu).
# Backs up replaced files to a timestamped folder, then restarts PM2.

set -e
APP_DIR=/var/www/ozawatraders
TS=$(date +%Y%m%d-%H%M%S)
BACKUP_DIR=$APP_DIR/.deploy-backup-$TS

echo "==> Backup directory: $BACKUP_DIR"
mkdir -p "$BACKUP_DIR"

echo "==> Writing views/partials/head.ejs"
mkdir -p "$(dirname "$APP_DIR/views/partials/head.ejs")"
mkdir -p "$(dirname "$BACKUP_DIR/views/partials/head.ejs")"
[ -f "$APP_DIR/views/partials/head.ejs" ] && cp "$APP_DIR/views/partials/head.ejs" "$BACKUP_DIR/views/partials/head.ejs"
cat > /tmp/_deploy.b64 <<'B64END'

B64END
base64 -d /tmp/_deploy.b64 > "$APP_DIR/views/partials/head.ejs"
rm /tmp/_deploy.b64
chown www-data:www-data "$APP_DIR/views/partials/head.ejs" 2>/dev/null || chown ec2-user:ec2-user "$APP_DIR/views/partials/head.ejs" 2>/dev/null || true


echo "==> Writing views/partials/footer.ejs"
mkdir -p "$(dirname "$APP_DIR/views/partials/footer.ejs")"
mkdir -p "$(dirname "$BACKUP_DIR/views/partials/footer.ejs")"
[ -f "$APP_DIR/views/partials/footer.ejs" ] && cp "$APP_DIR/views/partials/footer.ejs" "$BACKUP_DIR/views/partials/footer.ejs"
cat > /tmp/_deploy.b64 <<'B64END'

B64END
base64 -d /tmp/_deploy.b64 > "$APP_DIR/views/partials/footer.ejs"
rm /tmp/_deploy.b64
chown www-data:www-data "$APP_DIR/views/partials/footer.ejs" 2>/dev/null || chown ec2-user:ec2-user "$APP_DIR/views/partials/footer.ejs" 2>/dev/null || true


echo "==> Writing views/index.ejs"
mkdir -p "$(dirname "$APP_DIR/views/index.ejs")"
mkdir -p "$(dirname "$BACKUP_DIR/views/index.ejs")"
[ -f "$APP_DIR/views/index.ejs" ] && cp "$APP_DIR/views/index.ejs" "$BACKUP_DIR/views/index.ejs"
cat > /tmp/_deploy.b64 <<'B64END'

B64END
base64 -d /tmp/_deploy.b64 > "$APP_DIR/views/index.ejs"
rm /tmp/_deploy.b64
chown www-data:www-data "$APP_DIR/views/index.ejs" 2>/dev/null || chown ec2-user:ec2-user "$APP_DIR/views/index.ejs" 2>/dev/null || true


echo "==> Writing views/category.ejs"
mkdir -p "$(dirname "$APP_DIR/views/category.ejs")"
mkdir -p "$(dirname "$BACKUP_DIR/views/category.ejs")"
[ -f "$APP_DIR/views/category.ejs" ] && cp "$APP_DIR/views/category.ejs" "$BACKUP_DIR/views/category.ejs"
cat > /tmp/_deploy.b64 <<'B64END'

B64END
base64 -d /tmp/_deploy.b64 > "$APP_DIR/views/category.ejs"
rm /tmp/_deploy.b64
chown www-data:www-data "$APP_DIR/views/category.ejs" 2>/dev/null || chown ec2-user:ec2-user "$APP_DIR/views/category.ejs" 2>/dev/null || true


echo "==> Writing views/customer.ejs"
mkdir -p "$(dirname "$APP_DIR/views/customer.ejs")"
mkdir -p "$(dirname "$BACKUP_DIR/views/customer.ejs")"
[ -f "$APP_DIR/views/customer.ejs" ] && cp "$APP_DIR/views/customer.ejs" "$BACKUP_DIR/views/customer.ejs"
cat > /tmp/_deploy.b64 <<'B64END'

B64END
base64 -d /tmp/_deploy.b64 > "$APP_DIR/views/customer.ejs"
rm /tmp/_deploy.b64
chown www-data:www-data "$APP_DIR/views/customer.ejs" 2>/dev/null || chown ec2-user:ec2-user "$APP_DIR/views/customer.ejs" 2>/dev/null || true


echo "==> Writing views/contact.ejs"
mkdir -p "$(dirname "$APP_DIR/views/contact.ejs")"
mkdir -p "$(dirname "$BACKUP_DIR/views/contact.ejs")"
[ -f "$APP_DIR/views/contact.ejs" ] && cp "$APP_DIR/views/contact.ejs" "$BACKUP_DIR/views/contact.ejs"
cat > /tmp/_deploy.b64 <<'B64END'

B64END
base64 -d /tmp/_deploy.b64 > "$APP_DIR/views/contact.ejs"
rm /tmp/_deploy.b64
chown www-data:www-data "$APP_DIR/views/contact.ejs" 2>/dev/null || chown ec2-user:ec2-user "$APP_DIR/views/contact.ejs" 2>/dev/null || true

echo "==> Restarting PM2 (clears EJS view cache)"
pm2 restart ozawatraders 2>/dev/null || pm2 restart all

echo "==> Waiting 3s then verifying live URLs"
sleep 3
for p in / /customer /contact /power-cabinet /micro-feeder /rad; do
    code=$(curl -sk -o /dev/null -w '%{http_code}' "https://ozawatraders.org$p")
    printf "   %-20s status:%s\n" "$p" "$code"
done

echo "==> Done. Backup at $BACKUP_DIR"
echo "    Rollback: cp -r \"$BACKUP_DIR\"/views/* \"$APP_DIR\"/views/ && pm2 restart ozawatraders"
